"""Validators over depot run outputs (continued from validators.py).

Each validator vN(items) returns (passed, measured).
"""

from collections import Counter

# Inclusive bounds for supplier reliability (V9).
# Assumed 0..100 (a percentage); the spec range was not provided.
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def v7(items):
    """V7: every warehouse's capacity was respected across runs.

    items: list of {"wh": str, "capacity": int, "max_units": int}.
    measured: list of wh names whose max_units exceeded capacity
    (one entry per offending record, in input order).
    """
    bad = [entry["wh"] for entry in items if entry["max_units"] > entry["capacity"]]
    return (len(bad) == 0, bad)


def _missing_notifications(entry):
    """Return the expired [sku, wh, qty] triples with no matching notification.

    Matching is by full triple and respects multiplicity: each notified
    triple can cover one expired triple.
    """
    notified = Counter(tuple(triple) for triple in entry["notified"])
    missing = []
    for triple in entry["expired"]:
        key = tuple(triple)
        if notified[key] > 0:
            notified[key] -= 1
        else:
            missing.append(key)
    return missing


def v8(items):
    """V8: all expiries were notified.

    items: list of {"expired": [[sku, wh, qty], ...],
                    "notified": [[sku, wh, qty], ...]}.
    measured: list of (sku, wh, qty) tuples for expiries with no notification
    (across all entries, in input order).
    """
    bad = []
    for entry in items:
        bad.extend(_missing_notifications(entry))
    return (len(bad) == 0, bad)


def _out_of_range(value):
    """True if a reliability value falls outside the inclusive bounds."""
    return value < RELIABILITY_MIN or value > RELIABILITY_MAX


def v9(items):
    """V9: every supplier's reliability stayed in range.

    items: list of {"supplier": str, "reliability": int}.
    Range is inclusive: RELIABILITY_MIN <= reliability <= RELIABILITY_MAX.
    measured: list of supplier names with out-of-range reliability
    (one entry per offending record, in input order).
    """
    bad = [e["supplier"] for e in items if _out_of_range(e["reliability"])]
    return (len(bad) == 0, bad)
