import unittest

from validators_later import v7, v8, v9


class TestV7(unittest.TestCase):
    def test_empty_passes(self):
        self.assertEqual(v7([]), (True, []))

    def test_within_capacity_passes(self):
        items = [{"wh": "A", "capacity": 10, "max_units": 10}]
        self.assertEqual(v7(items), (True, []))

    def test_over_capacity_fails(self):
        items = [
            {"wh": "A", "capacity": 10, "max_units": 11},
            {"wh": "B", "capacity": 10, "max_units": 5},
            {"wh": "C", "capacity": 3, "max_units": 4},
        ]
        self.assertEqual(v7(items), (False, ["A", "C"]))


class TestV8(unittest.TestCase):
    def test_empty_passes(self):
        self.assertEqual(v8([]), (True, []))

    def test_all_notified_passes(self):
        items = [{
            "expired": [["s1", "W1", 2]],
            "notified": [["s1", "W1", 2]],
        }]
        self.assertEqual(v8(items), (True, []))

    def test_missing_notification_fails(self):
        items = [{
            "expired": [["s1", "W1", 2], ["s2", "W1", 5]],
            "notified": [["s1", "W1", 2]],
        }]
        self.assertEqual(v8(items), (False, [("s2", "W1", 5)]))

    def test_quantity_mismatch_fails(self):
        items = [{
            "expired": [["s1", "W1", 2]],
            "notified": [["s1", "W1", 3]],
        }]
        self.assertEqual(v8(items), (False, [("s1", "W1", 2)]))

    def test_duplicate_expiries_need_duplicate_notifications(self):
        items = [{
            "expired": [["s1", "W1", 2], ["s1", "W1", 2]],
            "notified": [["s1", "W1", 2]],
        }]
        self.assertEqual(v8(items), (False, [("s1", "W1", 2)]))

    def test_notifications_do_not_cross_entries(self):
        items = [
            {"expired": [["s1", "W1", 2]], "notified": [["s1", "W1", 2]]},
            {"expired": [["s1", "W1", 2]], "notified": []},
        ]
        self.assertEqual(v8(items), (False, [("s1", "W1", 2)]))


class TestV9(unittest.TestCase):
    def test_empty_passes(self):
        self.assertEqual(v9([]), (True, []))

    def test_bounds_are_inclusive(self):
        items = [
            {"supplier": "lo", "reliability": 0},
            {"supplier": "hi", "reliability": 100},
        ]
        self.assertEqual(v9(items), (True, []))

    def test_out_of_range_fails(self):
        items = [
            {"supplier": "neg", "reliability": -1},
            {"supplier": "ok", "reliability": 50},
            {"supplier": "big", "reliability": 101},
        ]
        self.assertEqual(v9(items), (False, ["neg", "big"]))


if __name__ == "__main__":
    unittest.main()
